drop database if exists organization_management_system;
create database organization_management_system;
use organization_management_system;
create table office(office_id int auto_increment primary key, office_name varchar(100) not null, address varchar(100), phone_number varchar(20), opening_date date);
create table department(department_id int auto_increment primary key, office_id int not null, department_name varchar(100) not null, description varchar(100), foreign key(office_id) references office(office_id));
create table staff(staff_id int auto_increment primary key, first_name varchar(50) not null, last_name varchar(50) not null, date_of_birth date, email varchar(100) unique not null, phone_number varchar(20), job_title varchar(50), date_hired date, employment_status varchar(20));
create table department_assignment(assignment_id int auto_increment primary key, staff_id int not null, department_id int not null, start_date date, end_date date, foreign key(staff_id) references staff(staff_id), foreign key(department_id) references department(department_id));
create table project(project_id int auto_increment primary key, office_id int not null, project_title varchar(100) not null, description varchar(100), start_date date, expected_end_date date, budget int, status varchar(20), foreign key(office_id) references office(office_id));
create table project_participation(participation_id int auto_increment primary key, project_id int not null, staff_id int not null, project_role varchar(50), date_joined date, date_stopped date, foreign key(project_id) references project(project_id), foreign key(staff_id) references staff(staff_id));
create table equipment(equipment_id int auto_increment primary key, asset_tag varchar(20) not null unique, item_type varchar(50), make_model varchar(50), purchase_date date, condition_status varchar(20), current_status varchar(20));
create table equipment_assignment(assignment_id int auto_increment primary key, equipment_id int not null, staff_id int not null, issue_date date, return_date date, return_condition varchar(20), foreign key(equipment_id) references equipment(equipment_id), foreign key(staff_id) references staff(staff_id));
