use organization_management_system;
select * from office;
select * from department;
select * from staff;
select * from department_assignment;
select * from project;
select * from project_participation;
select * from equipment;
select * from equipment_assignment;
select s.first_name, s.last_name, d.department_name from staff s join department_assignment da on s.staff_id = da.staff_id join department d on da.department_id = d.department_id;
select o.office_name, count(d.department_id) as total_departments from office o join department d on o.office_id = d.office_id group by o.office_name;
select p.project_title, o.office_name, p.status from project p join office o on p.office_id = o.office_id;
select s.first_name, e.asset_tag, e.item_type, ea.issue_date from staff s join equipment_assignment ea on s.staff_id = ea.staff_id join equipment e on ea.equipment_id = e.equipment_id;
